import json
import os
import urllib.request

# The old prices.internal host was retired; the service moved to
# pricing-v2.internal:8081 and now serves the v2 API:
#   GET /api/v2/price/{sku}  ->  {"price": <number>}
# It requires an X-Pricing-Key API key. The base URL and key are configurable
# via environment so they can follow future service moves without code changes.
BASE = os.environ.get("PRICES_BASE_URL", "http://pricing-v2.internal:8081/api/v2/price")
API_KEY = os.environ.get("PRICES_API_KEY", "")


def get_price(sku: str) -> float:
    req = urllib.request.Request(f"{BASE}/{sku}")
    if API_KEY:
        req.add_header("X-Pricing-Key", API_KEY)
    with urllib.request.urlopen(req, timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
PY
